from __future__ import annotations

import numpy as np

from matchms.reference_spectra import (
    aspirin, cocaine, glucose, hydroxy_cholesterol, phenylalanine, salicin,
)
from matchms.similarity.flash_utils import _clean_and_weight

TOL = 0.02

spectra = [aspirin(), cocaine(), glucose(), hydroxy_cholesterol(), phenylalanine(), salicin()]
names = ["aspirin", "cocaine", "glucose", "hydroxy_chol", "phenylal", "salicin"]

def prep(s):
    pmz = s.metadata.get("precursor_mz", None)
    return _clean_and_weight(
        s.peaks.to_numpy, pmz,
        remove_precursor=False, precursor_window=1.6,
        noise_cutoff=0.0, normalize_to_half=True, merge_within_da=0.0,
        weighing_type="entropy", dtype=np.float64)

C = [prep(s) for s in spectra]

def xlog2(x):
    return 0.0 if x <= 0 else x * np.log2(x)

xlog2v = np.vectorize(xlog2)

def simulate(a, b, mode):
    """entropy-like score between cleaned peaks a, b (columns mz,I), under given rule."""
    score = 0.0
    if mode == "per_pair":  # current code
        for mz_a, ia in a:
            for mz_b, ib in b:
                if abs(mz_a - mz_b) <= TOL:
                    score += xlog2(ia + ib) - xlog2(ia) - xlog2(ib)
        return score
    if mode == "per_unique_peak":
        s1 = 0.0
        match_a = np.zeros(len(a), bool)
        match_b = np.zeros(len(b), bool)
        for i, (mz_a, ia) in enumerate(a):
            for j, (mz_b, ib) in enumerate(b):
                if abs(mz_a - mz_b) <= TOL:
                    s1 += xlog2(ia + ib)
                    match_a[i] = True
                    match_b[j] = True
        return s1 - float(xlog2v(a[match_a, 1]).sum()) - float(xlog2v(b[match_b, 1]).sum())
    if mode == "greedy":  # one-to-one by product intensity, then entropy pairs
        pairs = []
        for i, (mz_a, ia) in enumerate(a):
            for j, (mz_b, ib) in enumerate(b):
                if abs(mz_a - mz_b) <= TOL:
                    pairs.append((ia * ib, i, j))
        pairs.sort(reverse=True)
        used_a = np.zeros(len(a), bool)
        used_b = np.zeros(len(b), bool)
        for _, i, j in pairs:
            if used_a[i] or used_b[j]:
                continue
            used_a[i] = used_b[j] = True
            score += xlog2(a[i, 1] + b[j, 1]) - xlog2(a[i, 1]) - xlog2(b[j, 1])
        return score
    if mode == "closest":  # per query peak, keep closest lib peak per spectrum
        used_b = np.zeros(len(b), bool)
        s1 = 0.0
        for i, (mz_a, ia) in enumerate(a):
            best = None
            for j, (mz_b, ib) in enumerate(b):
                d = abs(mz_a - mz_b)
                if d <= TOL and (best is None or d < best[0]):
                    best = (d, j)
            if best is not None:
                used_b[best[1]] = True
        # one-to-one conflicts possible; do greedy by distance instead
        pairs = []
        for i, (mz_a, ia) in enumerate(a):
            for j, (mz_b, ib) in enumerate(b):
                d = abs(mz_a - mz_b)
                if d <= TOL:
                    pairs.append((d, i, j))
        pairs.sort()
        used_a = np.zeros(len(a), bool)
        used_b = np.zeros(len(b), bool)
        for d, i, j in pairs:
            if used_a[i] or used_b[j]:
                continue
            used_a[i] = used_b[j] = True
            score += xlog2(a[i, 1] + b[j, 1]) - xlog2(a[i, 1]) - xlog2(b[j, 1])
        return score
    if mode == "merged":  # merge within tol first, then per-pair
        def merge(peaks):
            if len(peaks) <= 1:
                return peaks
            out_mz, out_i = [], []
            cm, ci = peaks[0]
            for m, i_ in peaks[1:]:
                if m - cm <= TOL:
                    t = ci + i_
                    cm = (cm * ci + m * i_) / t
                    ci = t
                else:
                    out_mz.append(cm); out_i.append(ci)
                    cm, ci = m, i_
            out_mz.append(cm); out_i.append(ci)
            return np.column_stack([out_mz, out_i])
        ma, mb = merge(a), merge(b)
        # renormalize merged to 0.5
        ma = ma.copy(); ma[:, 1] *= 0.5 / ma[:, 1].sum()
        mb = mb.copy(); mb[:, 1] *= 0.5 / mb[:, 1].sum()
        for mz_a, ia in ma:
            for mz_b, ib in mb:
                if abs(mz_a - mz_b) <= TOL:
                    score += xlog2(ia + ib) - xlog2(ia) - xlog2(ib)
        return score
    raise ValueError(mode)

for mode in ["per_pair", "per_unique_peak", "greedy", "closest", "merged"]:
    M = np.zeros((6, 6))
    for i in range(6):
        for j in range(6):
            M[i, j] = simulate(C[i], C[j], mode)
    d = np.diag(M)
    print(f"\n=== {mode} ===")
    print("diag:", np.round(d, 6))
    print("min:", M.min(), "max:", M.max(), "mean:", M.mean())
    print("bounded:", bool((M >= -1e-12).all() and (M <= 1 + 1e-9).all()),
          "diag_ok:", bool(np.allclose(d, 1.0, atol=1e-6)),
          "symmetric:", bool(np.allclose(M, M.T)))
